INSERT INTO logicore_tasks (task_id, title, description, priority, status, assigned_to, created_by, created_at, due_date, progress, subtasks, attachments, category, location_ref) VALUES
  ('tsk-001', 'Conduct Monthly Fleet Inspection', 'Perform a full physical inspection of all transport vehicles at EC Yard. Document tyre condition, fluid levels, bodywork and license expiry status.', 'High', 'In Progress', '["usr-001","usr-002"]'::jsonb, 'usr-admin', '2026-09-23', '2026-10-01', 45, '[{"id":"st-1a","label":"Inspect all transport vehicles","done":true},{"id":"st-1b","label":"Check U Rent fleet","done":true},{"id":"st-1c","label":"Document findings in system","done":false},{"id":"st-1d","label":"Submit report to management","done":false}]'::jsonb, '[]'::jsonb, 'Fleet Maintenance', NULL),
  ('tsk-002', 'Update Operator Placement Records – AMSA Vanderbijlpark', 'Review and update all operator placement records for the AMSA - Vanderbijlpark site. Ensure contract dates, machine allocations and PO numbers are current.', 'Urgent', 'Not Started', '["usr-admin"]'::jsonb, 'usr-admin', '2026-09-26', '2026-09-29', 0, '[{"id":"st-2a","label":"Pull current placement data","done":false},{"id":"st-2b","label":"Verify machine-operator links","done":false},{"id":"st-2c","label":"Update PO numbers","done":false}]'::jsonb, '[]'::jsonb, 'Administration', NULL),
  ('tsk-003', 'Service Telehandler TLH-002 – Zondereinde', 'Schedule and oversee the 500-hour service of TLH-002 currently on site at Zondereinde. Coordinate with the site manager for downtime window.', 'Critical', 'Delayed', '["usr-002","usr-003"]'::jsonb, 'usr-admin', '2026-09-18', '2026-09-26', 20, '[{"id":"st-3a","label":"Book service slot with technician","done":true},{"id":"st-3b","label":"Order replacement filters","done":false},{"id":"st-3c","label":"Execute service on site","done":false},{"id":"st-3d","label":"Update service records in LogiCore","done":false}]'::jsonb, '[{"name":"TLH-002_Service_Manual.pdf","url":"#"}]'::jsonb, 'Heavy Equipment', NULL),
  ('tsk-004', 'Capture Inventory Stock Count – HQ Store', 'Perform full inventory count at the EC Yard main store. Reconcile physical quantities with system records and flag discrepancies.', 'Normal', 'Completed', '["usr-001"]'::jsonb, 'usr-admin', '2026-09-14', '2026-09-21', 100, '[{"id":"st-4a","label":"Print current stock report","done":true},{"id":"st-4b","label":"Physical count – Power Tools","done":true},{"id":"st-4c","label":"Physical count – Lifting & Rigging","done":true},{"id":"st-4d","label":"Update system quantities","done":true}]'::jsonb, '[{"name":"StockCount_Report_Jun26.xlsx","url":"#"}]'::jsonb, 'Inventory', NULL),
  ('tsk-005', 'Renew Driver Licenses – 3 Operators', 'Arrange renewals for the three operators whose PrDP licenses expire within the next 30 days. Book appointments at the licencing department.', 'High', 'In Progress', '["usr-admin","usr-004"]'::jsonb, 'usr-admin', '2026-09-25', '2026-10-05', 60, '[{"id":"st-5a","label":"Identify expiring licenses","done":true},{"id":"st-5b","label":"Book licencing appointments","done":true},{"id":"st-5c","label":"Attend appointments","done":false},{"id":"st-5d","label":"Scan and upload new licenses","done":false}]'::jsonb, '[]'::jsonb, 'Compliance', NULL),
  ('tsk-006', 'Install GPS Tracker on ECR-047', 'Coordinate installation of the Netstar GPS unit on fleet vehicle ECR-047. Vehicle must be at HQ for at least 4 hours for the install.', 'Normal', 'Not Started', '["usr-003"]'::jsonb, 'usr-admin', '2026-09-27', '2026-10-03', 0, '[{"id":"st-6a","label":"Schedule installation with Netstar","done":false},{"id":"st-6b","label":"Arrange vehicle availability at HQ","done":false},{"id":"st-6c","label":"Confirm unit is activated in system","done":false}]'::jsonb, '[]'::jsonb, 'Fleet Maintenance', NULL),
  ('tsk-007', 'Prepare Monthly KPI Report – May 2026', 'Compile the monthly KPI report covering fleet utilisation, operator hours, heavy equipment on-hire rates and inventory movements for May 2026.', 'High', 'On Hold', '["usr-admin"]'::jsonb, 'usr-admin', '2026-09-20', '2026-09-30', 35, '[{"id":"st-7a","label":"Export fleet data from LogiCore","done":true},{"id":"st-7b","label":"Compile operator hours spreadsheet","done":false},{"id":"st-7c","label":"Write narrative summary","done":false},{"id":"st-7d","label":"Submit to MD for approval","done":false}]'::jsonb, '[{"name":"KPI_Template_May26.xlsx","url":"#"}]'::jsonb, 'Reporting', NULL),
  ('tsk-008', 'Offboard Container CNT-DBKU2151190 – Sasol', 'Process the off-hire of container DBKU2151190 from the Sasol site. Arrange collection, update status in system, and file collection documentation.', 'Low', 'Completed', '["usr-002"]'::jsonb, 'usr-admin', '2026-09-08', '2026-09-18', 100, '[{"id":"st-8a","label":"Notify supplier of off-hire","done":true},{"id":"st-8b","label":"Update container status in LogiCore","done":true},{"id":"st-8c","label":"File signed collection document","done":true}]'::jsonb, '[{"name":"OffHire_DBKU2151190.pdf","url":"#"}]'::jsonb, 'Heavy Equipment', NULL),
  ('tsk-009', 'Audit Rigging Equipment – Ilikwa Site', 'Conduct a full audit of all lifting and rigging equipment deployed at the Ilikwa site. Check load test certificates and quarantine any out-of-cert items.', 'Urgent', 'Not Started', '["usr-004","usr-005"]'::jsonb, 'usr-admin', '2026-09-27', '2026-10-02', 0, '[{"id":"st-9a","label":"Print current Ilikwa asset list","done":false},{"id":"st-9b","label":"Travel to site and conduct audit","done":false},{"id":"st-9c","label":"Quarantine out-of-cert items","done":false},{"id":"st-9d","label":"Submit audit report","done":false}]'::jsonb, '[]'::jsonb, 'Compliance', NULL),
  ('tsk-010', 'Update Lease Agreements – U Rent Fleet', 'Review and update all U Rent lease agreement documents in the File Vault. Ensure start dates, account numbers and project codes are correct.', 'Normal', 'Delayed', '["usr-admin"]'::jsonb, 'usr-admin', '2026-09-16', '2026-09-25', 30, '[{"id":"st-10a","label":"Download current lease docs","done":true},{"id":"st-10b","label":"Cross-reference with system data","done":false},{"id":"st-10c","label":"Upload corrected documents","done":false}]'::jsonb, '[]'::jsonb, 'Administration', NULL),
  ('tsk-011', 'Onboard New Operator – Rustenburg Site', 'Complete the onboarding process for the new telehandler operator being deployed to the Rustenburg site. Create LogiCore profile, collect documents, assign assets.', 'High', 'In Progress', '["usr-admin","usr-001"]'::jsonb, 'usr-admin', '2026-09-24', '2026-09-30', 75, '[{"id":"st-11a","label":"Create user profile in LogiCore","done":true},{"id":"st-11b","label":"Collect ID and license copies","done":true},{"id":"st-11c","label":"Assign equipment in system","done":true},{"id":"st-11d","label":"Conduct site induction","done":false}]'::jsonb, '[]'::jsonb, 'HR', NULL),
  ('tsk-012', 'Replace Worn Tyres – ECR-034 & ECR-019', 'Source and fit replacement tyres on ECR-034 (2x rear) and ECR-019 (1x front). Vehicles must be taken off-site to approved fitment centre.', 'Normal', 'Not Started', '["usr-003"]'::jsonb, 'usr-admin', '2026-09-28', '2026-10-04', 0, '[{"id":"st-12a","label":"Source tyre quotes","done":false},{"id":"st-12b","label":"Get approval for spend","done":false},{"id":"st-12c","label":"Drop vehicles at fitment centre","done":false},{"id":"st-12d","label":"Collect vehicles and log maintenance","done":false}]'::jsonb, '[]'::jsonb, 'Fleet Maintenance', NULL);
